import express from "express";
import { createRequestHandler } from "@kasperrt/smolter/utils/http";
import * as build from "./dist/server/index.js";
import manifest from "./dist/client/.vite/manifest.json" with { type: "json" };

const app = express();
const client = manifest["index.html"];

// Mount your Prometheus and tracing middleware here, before Smolter.
app.use("/assets", express.static("dist/client/assets", {
  immutable: true,
  maxAge: "1y",
}));

app.use(createRequestHandler({
  build,
  entry: `/assets/${client.file.replace(/^assets\//, "")}`,
}));

app.listen(3000);

createRequestHandler({ build, entry, maxBodySize: 8 * 1024 * 1024 });
// Match the production limit in Vite:
applicationPlugins({ maxBodySize: 8 * 1024 * 1024 });
